-- Confirm-Open step for CO (PROJECT_PLAN §6.4.1/§6.13, decisions #30/#31; TODO Track 2).
-- GENERATED by scripts/etl/gen_confirm_open.sh co — edit the generator, not this file.
-- "GREEN must be earned": where PAD-US says open (GREEN) but the authoritative CO ownership
-- layer (BLM Colorado SMA) shows NO public land within ~100m, the open status is unconfirmed -> YELLOW.
-- Buffer-carve (Utah pattern): parcels the source maps as NOT-public (private/tribal/water/null)
-- are carved back out of the buffer so adjacency never blankets a known-not-public parcel.
-- Prereq: staging.sma_co loaded (scripts/etl/pull_sma.sh co); legality_polygons built (unify.sql).
-- Idempotent: deletes prior blmsma_co rows first.
SET client_min_messages TO WARNING;

DELETE FROM tiles.legality_polygons WHERE source_key = 'blmsma_co';

DROP TABLE IF EXISTS staging.conf_notpub_co;
-- SubDivide the not-public side too: wall-to-wall states (CO) have thousands of large private
-- multipolygons, and un-subdivided carve unions OOM-crashed the dev Postgres (2026-07-12).
-- Small pieces keep every LATERAL union local and bounded.
CREATE TABLE staging.conf_notpub_co AS
  SELECT ST_SubDivide(ST_MakeValid(geom), 512) AS geom FROM staging.sma_co
  WHERE NOT (upper(adm_code) IN ('BLM','BLM_LU','USFS','USFS_LU','USFS_NG','NPS','USFW','BOR','STA','LOCAL','DOD'));
-- PARCEL-GRADE CARVE (Tier-1 validation finding, 2026-07-12): SMA sources are GCDB/PLSS-grade
-- and miss parcel-sized private inholdings inside blocks they map federal — the validation
-- caught 9 real false-GREENs in CO/NM cabin/ranch country. Where county parcel data is loaded
-- (staging.parcels), assessor-confirmed private parcels join the carve, giving those counties
-- Utah-grade resolution. No-op where staging.parcels is absent or has no rows for the state.
INSERT INTO staging.conf_notpub_co
  SELECT ST_SubDivide(ST_MakeValid(geom), 512)
  FROM staging.parcels
  WHERE to_regclass('staging.parcels') IS NOT NULL
    AND state = 'CO' AND owner_class = 'private';
CREATE INDEX conf_notpub_co_gix ON staging.conf_notpub_co USING GIST (geom);

DROP TABLE IF EXISTS staging.conf_buf_co;
CREATE TABLE staging.conf_buf_co AS
  SELECT ST_CollectionExtract(ST_MakeValid(ST_Difference(b.geom,
           COALESCE(np.geom, ST_GeomFromText('MULTIPOLYGON EMPTY', 4326)))), 3) AS geom
  FROM (SELECT ST_Transform(ST_Buffer(ST_Transform(ST_SubDivide(ST_MakeValid(geom), 512), 5070), 100), 4326) AS geom
        FROM staging.sma_co
        WHERE upper(adm_code) IN ('BLM','BLM_LU','USFS','USFS_LU','USFS_NG','NPS','USFW','BOR','STA','LOCAL','DOD')) b
  LEFT JOIN LATERAL (
    SELECT ST_Union(n.geom) AS geom FROM staging.conf_notpub_co n WHERE ST_Intersects(n.geom, b.geom)
  ) np ON true;
CREATE INDEX conf_buf_co_gix ON staging.conf_buf_co USING GIST (geom);

INSERT INTO tiles.legality_polygons
  (geom, verdict, reason, land_manager, unit_nm, protection_status, state_nm, data_vintage, source_key)
SELECT ST_Multi(d.geom), 'YELLOW',
  'Open status not confirmed by CO public-ownership data (BLM Colorado SMA) — possibly private; verify before collecting.',
  NULL, NULL, 'unconfirmed-open', 'CO', 'BLM CO SMA (updated daily; pulled 2026-07) (confirm-open vs PAD-US)', 'blmsma_co'
FROM (
  SELECT (ST_Dump(
            ST_CollectionExtract(
              ST_MakeValid(ST_Difference(g.geom,
                COALESCE(b.buf, ST_GeomFromText('MULTIPOLYGON EMPTY', 4326)))), 3))).geom AS geom
  FROM (SELECT ST_Subdivide(geom, 256) AS geom FROM tiles.legality_polygons
        WHERE state_nm='CO' AND verdict='GREEN' AND source_key='padus') g
  LEFT JOIN LATERAL (
    SELECT ST_Union(cb.geom) AS buf FROM staging.conf_buf_co cb WHERE ST_DWithin(cb.geom, g.geom, 0.003)
  ) b ON true
) d
WHERE d.geom IS NOT NULL AND NOT ST_IsEmpty(d.geom) AND ST_Area(d.geom::geography) > 1000;

SELECT count(*) AS unconfirmed_polys, round((sum(ST_Area(geom::geography))/1e6)::numeric, 2) AS km2
FROM tiles.legality_polygons WHERE source_key = 'blmsma_co';
